#!/bin/sh
set -e

# Start K3s in the background
# Pass arguments to k3s server if needed, or just hardcode as per previous compose
echo "Starting K3s server..."
/bin/k3s server --tls-san localhost --tls-san k3s &
K3S_PID=$!

# Wait for Kubeconfig to be generated by K3s
export KUBECONFIG_FILE=/output/kubeconfig.yaml
echo "Waiting for kubeconfig at $KUBECONFIG_FILE..."
timeout=60
while [ ! -f "$KUBECONFIG_FILE" ]; do
  sleep 1
  timeout=$((timeout-1))
  if [ "$timeout" -le 0 ]; then
    echo "Timed out waiting for kubeconfig"
    exit 1
  fi
done

# Prepare kubeconfig for internal use (save to shared volume)
echo "Preparing internal kubeconfig..."
cp "$KUBECONFIG_FILE" /output/kubeconfig-internal.yaml
sed -i 's/127.0.0.1/k3s/g' /output/kubeconfig-internal.yaml
sed -i 's/localhost/k3s/g' /output/kubeconfig-internal.yaml
chmod 666 /output/kubeconfig-internal.yaml

# Use localhost config for this script operations to ensure connectivity
export KUBECONFIG=/output/kubeconfig.yaml

echo "Waiting for K3s API..."
until kubectl cluster-info; do
  echo "K3s not ready yet..."
  sleep 2
done
echo "K3s is ready!"

# Install KEDA
echo "Installing KEDA..."
kubectl apply --server-side --force-conflicts -f https://github.com/kedacore/keda/releases/download/v2.12.0/keda-2.12.0.yaml

# Install Karpenter CRDs
echo "Installing Karpenter CRDs..."
kubectl apply --server-side --force-conflicts -f https://raw.githubusercontent.com/aws/karpenter-provider-aws/v0.32.1/pkg/apis/crds/karpenter.sh_nodepools.yaml
kubectl apply --server-side --force-conflicts -f https://raw.githubusercontent.com/aws/karpenter-provider-aws/v0.32.1/pkg/apis/crds/karpenter.k8s.aws_ec2nodeclasses.yaml
kubectl apply --server-side --force-conflicts -f https://raw.githubusercontent.com/aws/karpenter-provider-aws/v0.32.1/pkg/apis/crds/karpenter.sh_nodeclaims.yaml

# Apply Local Manifests
echo "Applying Local Manifests..."
if [ -d "/manifests/overlays/local" ]; then
    echo "Applying Kustomize overlay from /manifests/overlays/local..."
    kubectl apply --server-side --force-conflicts -k /manifests/overlays/local
else
    echo "Warning: /manifests/overlays/local directory not found."
fi

echo "K8s Setup Complete!"

# Create a marker file for healthcheck
touch /tmp/k3s-ready

# Wait for the K3s process to finish (which should be never unless killed)
wait "$K3S_PID"
